def safe_int(val, default):
    try:
        return int(val) if val is not None and val != '' else default
    except:
        return default

def parse_heure(val):
    """Parse un champ heure HTML (HH:MM ou H) → retourne (heure_int, minute_int) ou (None, 0)"""
    if not val:
        return None, 0
    val = str(val).strip()
    if ':' in val:
        parts = val.split(':')
        try:
            return int(parts[0]), int(parts[1]) if len(parts) > 1 else 0
        except:
            return None, 0
    try:
        return int(val), 0
    except:
        return None, 0

def parse_heure_minute(data, i):
    """Lit l'heure de naissance de la personne i.
    merci.html envoie l'heure et la minute déjà séparées en deux champs
    (heureN = heure, minuteN = minute) -- on les lit directement en priorité.
    Fallback sur parse_heure() pour rester compatible avec un éventuel appel
    qui enverrait encore un seul champ "HH:MM".
    Avant ce correctif, heureN était re-parsé seul via parse_heure(), qui ne
    trouve pas de ":" dans une simple heure entière et retombe donc toujours
    sur minute=0 -- les minutes saisies par le client étaient silencieusement
    perdues, ce qui faussait le calcul de l'Ascendant.
    """
    heure_val = data.get(f'heure{i}')
    minute_val = data.get(f'minute{i}')
    if minute_val not in (None, ''):
        h = safe_int(heure_val, None)
        m = safe_int(minute_val, 0)
        return h, m
    return parse_heure(heure_val)

def get_timezone(ville, lat=None, lon=None):
    """
    Retourne le nom du fuseau horaire IANA pour une ville.
    Si lat/lon sont fournis, utilise timezonefinder (précis).
    Sinon fallback sur une table de mots-clés, puis Europe/Paris.
    """
    # 1. timezonefinder (précis, basé sur les coordonnées)
    if lat is not None and lon is not None:
        try:
            from timezonefinder import TimezoneFinder
            tf = TimezoneFinder()
            tz = tf.timezone_at(lat=lat, lng=lon)
            if tz:
                return tz
        except Exception as _e:
            pass
    # 2. Fallback par mots-clés dans le nom de la ville
    TIMEZONE_MAP = {
        'france': 'Europe/Paris',
        'belgique': 'Europe/Brussels', 'suisse': 'Europe/Zurich',
        'canada': 'America/Montreal', 'maroc': 'Africa/Casablanca',
        'espagne': 'Europe/Madrid', 'italie': 'Europe/Rome',
        'london': 'Europe/London', 'angleterre': 'Europe/London',
        'new york': 'America/New_York', 'los angeles': 'America/Los_Angeles',
        'montreal': 'America/Montreal', 'québec': 'America/Montreal',
        'tokyo': 'Asia/Tokyo', 'japon': 'Asia/Tokyo',
        'casablanca': 'Africa/Casablanca', 'rabat': 'Africa/Casablanca',
    }
    if ville:
        ville_lower = ville.lower()
        for k, v in TIMEZONE_MAP.items():
            if k in ville_lower:
                return v
    if lat is not None and lon is not None and 41.0 <= float(lat) <= 51.5 and -5.5 <= float(lon) <= 10.0:
        return 'Europe/Paris'
    raise ValueError(f"Fuseau horaire introuvable pour {ville!r}")

