def deg_signe(deg):
    deg = deg % 360
    return SIGNES[int(deg//30)], round(deg%30, 1)

def _lon_ecliptique(p, epoch):
    """Longitude écliptique géocentrique apparente, exprimée à l'équinoxe de la date."""
    # PyEphem fournit g_ra/g_dec = position géocentrique apparente, epoch-of-date.
    # On reconstruit explicitement des coordonnées équatoriales de la même époque
    # avant conversion en écliptique, afin d'éviter les longitudes héliocentriques.
    eq = sw.Equatorial(p.g_ra, p.g_dec, epoch=epoch)
    ecl = sw.Ecliptic(eq, epoch=epoch)
    return math.degrees(float(ecl.lon)) % 360


def _calc_ascendant(obs, lat):
    """Calcule l'Ascendant tropical à partir du temps sidéral local et de la latitude."""
    # Formule de l'intersection orientale écliptique/horizon (Meeus).
    lst = float(obs.sidereal_time())  # radians, temps sidéral local apparent
    jd = sw.julian_date(obs)
    T = (jd - 2451545.0) / 36525.0
    # Obliquité moyenne de l'écliptique, suffisante à cette précision d'affichage.
    eps_deg = 23.0 + 26.0/60.0 + 21.448/3600.0 - (
        46.8150*T + 0.00059*T*T - 0.001813*T*T*T
    ) / 3600.0
    eps = math.radians(eps_deg)
    phi = math.radians(float(lat))
    asc = math.degrees(math.atan2(
        math.cos(lst),
        -(math.sin(lst) * math.cos(eps) + math.tan(phi) * math.sin(eps))
    )) % 360.0
    signe, degre = deg_signe(asc)
    return {'signe': signe, 'degre': degre}


def calc_theme(j, m, a, ville, heure=None, minute=0, asc_force=None):
    lat, lon = get_coords(ville)
    h = heure if heure is not None else 12
    minute = safe_int(minute, 0)
    dt_local = datetime(a, m, j, h, minute)

    # Conversion locale -> UTC avec gestion explicite de l'heure d'été.
    try:
        tz_name = get_timezone(ville, lat=lat, lon=lon)
        tz = pytz.timezone(tz_name)
        try:
            aware = tz.localize(dt_local, is_dst=None)
        except pytz.AmbiguousTimeError:
            # Heure répétée lors du passage à l'heure d'hiver : convention heure standard.
            aware = tz.localize(dt_local, is_dst=False)
        except pytz.NonExistentTimeError:
            # Heure sautée lors du passage à l'heure d'été : convention heure d'été.
            aware = tz.localize(dt_local, is_dst=True)
        dt_utc = aware.astimezone(pytz.UTC)
    except Exception as exc:
        raise ValueError(f"Impossible de déterminer le fuseau/UTC pour {ville!r}: {exc}") from exc

    obs = sw.Observer()
    obs.lat = str(lat)
    obs.lon = str(lon)
    obs.date = sw.Date(dt_utc.strftime('%Y/%m/%d %H:%M:%S'))
    obs.epoch = obs.date
    obs.pressure = 0  # pas de réfraction atmosphérique pour le thème natal

    planetes = {}
    erreurs_planetes = []
    for nom, cls in CORPS_EPHEM.items():
        try:
            p = cls(obs)
            lon_deg = _lon_ecliptique(p, obs.date)
            s, d = deg_signe(lon_deg)
            planetes[nom] = {'signe': s, 'degre': d}
        except Exception as exc:
            print(f"[astro] Position impossible pour {nom}: {exc}")
            erreurs_planetes.append(nom)
    if erreurs_planetes:
        raise ValueError(f"Calcul astrologique incomplet : {', '.join(erreurs_planetes)}")

    # Un Ascendant réel n'est calculable que si l'heure de naissance est connue.
    if heure is not None:
        try:
            asc_data = _calc_ascendant(obs, lat)
        except Exception as exc:
            print(f"[astro] Ascendant non calculé: {exc}")
            asc_data = {'signe': asc_force, 'degre': None} if asc_force else None
    else:
        asc_data = {'signe': asc_force, 'degre': None} if asc_force else None

    return {'planetes': planetes, 'ascendant': asc_data}

# ── Transits actuels sur le thème natal ─────────────────────────────────────

PLANETES_LENTES = ['Jupiter', 'Saturne', 'Uranus', 'Neptune']
ORBE_TRANSIT = 8.0  # degrés

def _lon_planete_today(cls):
    """Retourne la longitude écliptique géocentrique d'une planète à la date du jour (midi UTC)."""
    obs = sw.Observer()
    obs.lat = '48.8566'; obs.lon = '2.3522'
    today = date.today()
    obs.date = f"{today.year}/{today.month}/{today.day} 12"
    try:
        p = cls(obs)
        return _lon_ecliptique(p, obs.date)
    except Exception:
        return None

def _aspect_str(orbe, type_asp):
    if type_asp == 'conjonction':
        intensite = 'forte' if orbe < 3 else 'active'
    elif type_asp in ('opposition', 'carré'):
        intensite = 'tendue' if orbe < 4 else 'présente'
    else:
        intensite = 'harmonieuse' if orbe < 4 else 'légère'
    return f"{type_asp} {intensite} (orbe {orbe:.1f}°)"

def calc_transits(planetes_natales, j_naissance, m_naissance, a_naissance):
    """
    Calcule les transits majeurs des planètes lentes sur le thème natal.
    Retourne un bloc texte interne (jamais exposé au client).
    """
    aujourd_hui = date.today()
    age = aujourd_hui.year - a_naissance - (
        (aujourd_hui.month, aujourd_hui.day) < (m_naissance, j_naissance)
    )

    lignes = []

    for nom_transit, cls in [
        ('Jupiter', sw.Jupiter), ('Saturne', sw.Saturn),
        ('Uranus', sw.Uranus), ('Neptune', sw.Neptune)
    ]:
        lon_t = _lon_planete_today(cls)
        if lon_t is None:
            continue

        for nom_natal, data_natal in planetes_natales.items():
            try:
                idx_natal = SIGNES.index(data_natal['signe'])
                lon_n = idx_natal * 30 + float(data_natal.get('degre', 0) or 0)
            except (ValueError, TypeError):
                continue

            diff = abs(((lon_t - lon_n + 180) % 360) - 180)

            for angle, type_asp in [(0, 'conjonction'), (180, 'opposition'),
                                     (90, 'carré'), (120, 'trigone'), (60, 'sextile')]:
                orbe = abs(diff - angle)
                if orbe <= ORBE_TRANSIT:
                    # Filtrer les aspects trop mineurs sauf pour conj/opp/carré sur planètes perso
                    if type_asp in ('trigone', 'sextile') and nom_natal not in ('Soleil', 'Lune', 'Mercure', 'Vénus', 'Mars'):
                        continue
                    if nom_transit == nom_natal:
                        continue
                    lignes.append(
                        f"  {nom_transit} en transit : {_aspect_str(orbe, type_asp)} avec {nom_natal} natal"
                    )
                    break

    # Cycles de vie majeurs (Saturne, Jupiter)
    notes = []
    if 27 <= age <= 30:
        notes.append("  Retour de Saturne (1er) : phase de structuration identitaire, remise en question des bases")
    elif 57 <= age <= 60:
        notes.append("  Retour de Saturne (2e) : bilan de vie, transmission, repositionnement en profondeur")
    if 40 <= age <= 44:
        notes.append("  Opposition de Saturne : crise de mi-parcours, confrontation à ce qui n'a pas été construit")
    if age % 12 in (0, 1):
        notes.append(f"  Retour de Jupiter (~{age} ans) : année d'expansion, d'opportunités et de renouveau")

    if not lignes and not notes:
        return ""

    bloc = "\n\nCONTEXTE ASTROLOGIQUE ACTUEL — USAGE INTERNE UNIQUEMENT\n"
    bloc += "(Ne jamais mentionner planètes, transits ou termes astrologiques dans le texte livré.\n"
    bloc += "Ces données colorent l'analyse : tensions, cycles, énergie du moment — traduits en prose humaine.)\n"
    if lignes:
        bloc += "\nTransits actifs :\n" + "\n".join(lignes)
    if notes:
        bloc += "\nCycles de vie :\n" + "\n".join(notes)
    return bloc


# ── Roue du thème astral (SVG) ───────────────────────────────────────────────
SIGNES_ABBR = ['BÉLIER','TAUREAU','GÉMEAUX','CANCER','LION','VIERGE',
               'BALANCE','SCORPION','SAGITTAIRE','CAPRICORNE','VERSEAU','POISSONS']
PLANET_LABEL = {
    'Soleil':'SOLEIL','Lune':'LUNE','Mercure':'MERCURE','Vénus':'VÉNUS','Mars':'MARS',
    'Jupiter':'JUPITER','Saturne':'SATURNE','Uranus':'URANUS','Neptune':'NEPTUNE',
}

def _polar(cx, cy, r, lon_deg):
    theta = math.radians(lon_deg - 90)
    return cx + r * math.cos(theta), cy + r * math.sin(theta)

def build_natal_wheel_svg(planetes, ascendant=None):
    """Construit une roue zodiacale SVG à partir des positions planétaires réelles
    (calc_theme). Wheel illustrative : signes + planètes positionnés à leur degré
    exact, Ascendant marqué si connu. Pas de système de maisons (nécessiterait une
    heure de naissance fiable pour tous les cas, non garanti ici)."""
    cx = cy = 200
    r_outer, r_sign_in, r_tick_in, r_dot, r_label_base = 195, 158, 150, 140, 116

    parts = ['<svg viewBox="-35 -15 470 430" xmlns="http://www.w3.org/2000/svg" font-family="Jost, sans-serif">']
    parts.append(f'<circle cx="{cx}" cy="{cy}" r="{r_outer}" fill="none" stroke="#C9A84C" stroke-width="1" opacity=".55"/>')
    parts.append(f'<circle cx="{cx}" cy="{cy}" r="{r_sign_in}" fill="none" stroke="#C9A84C" stroke-width=".7" opacity=".4"/>')
    parts.append(f'<circle cx="{cx}" cy="{cy}" r="{r_tick_in-4}" fill="none" stroke="#C9A84C" stroke-width=".5" opacity=".25"/>')

    for i in range(12):
        a0, a1, mid = i*30, i*30+30, i*30+15
        if i % 2 == 0:
            x0,y0 = _polar(cx,cy,r_outer,a0); x1,y1 = _polar(cx,cy,r_outer,a1)
            xi1,yi1 = _polar(cx,cy,r_sign_in,a1); xi0,yi0 = _polar(cx,cy,r_sign_in,a0)
            parts.append(f'<path d="M{x0:.1f},{y0:.1f} A{r_outer},{r_outer} 0 0 1 {x1:.1f},{y1:.1f} L{xi1:.1f},{yi1:.1f} A{r_sign_in},{r_sign_in} 0 0 0 {xi0:.1f},{yi0:.1f} Z" fill="#C9A84C" opacity=".07"/>')
        xo,yo = _polar(cx,cy,r_outer,a0); xin,yin = _polar(cx,cy,r_sign_in,a0)
        parts.append(f'<line x1="{xin:.1f}" y1="{yin:.1f}" x2="{xo:.1f}" y2="{yo:.1f}" stroke="#C9A84C" stroke-width=".6" opacity=".4"/>')
        lx,ly = _polar(cx,cy,(r_outer+r_sign_in)/2, mid)
        parts.append(f'<text x="{lx:.1f}" y="{ly:.1f}" font-size="8.5" letter-spacing="1.5" fill="#B97333" text-anchor="middle" dominant-baseline="middle">{SIGNES_ABBR[i]}</text>')

    items = []
    for nom, d in (planetes or {}).items():
        try:
            idx = SIGNES.index(d['signe'])
        except (ValueError, KeyError, TypeError):
            continue
        items.append({'nom': nom, 'lon': idx*30 + float(d.get('degre',0) or 0)})
    items.sort(key=lambda it: it['lon'])
    used = []
    for it in items:
        tier = 0
        for u in used:
            if abs(((it['lon']-u['lon']+180)%360)-180) < 14 and u['tier']==tier:
                tier += 1
        it['tier'] = tier
        used.append(it)

    for it in items:
        lon = it['lon']
        xdot,ydot = _polar(cx,cy,r_dot,lon)
        parts.append(f'<circle cx="{xdot:.1f}" cy="{ydot:.1f}" r="3" fill="#B97333"/>')
        xt0,yt0 = _polar(cx,cy,r_tick_in,lon); xt1,yt1 = _polar(cx,cy,r_dot,lon)
        parts.append(f'<line x1="{xt0:.1f}" y1="{yt0:.1f}" x2="{xt1:.1f}" y2="{yt1:.1f}" stroke="#B97333" stroke-width=".5" opacity=".5"/>')
        rlabel = r_label_base - it['tier']*16
        xl,yl = _polar(cx,cy,rlabel,lon)
        parts.append(f'<line x1="{xdot:.1f}" y1="{ydot:.1f}" x2="{xl:.1f}" y2="{yl:.1f}" stroke="#B97333" stroke-width=".4" opacity=".35"/>')
        label = PLANET_LABEL.get(it['nom'], str(it['nom']).upper())
        parts.append(f'<text x="{xl:.1f}" y="{yl:.1f}" font-size="7" letter-spacing=".5" fill="#5A5240" text-anchor="middle" dominant-baseline="middle">{label}</text>')

    if ascendant and ascendant.get('signe'):
        try:
            idx = SIGNES.index(ascendant['signe'])
            lon = idx*30 + float(ascendant.get('degre') or 0)
            x0,y0 = _polar(cx,cy,r_sign_in,lon); x1,y1 = _polar(cx,cy,r_outer+8,lon)
            parts.append(f'<line x1="{x0:.1f}" y1="{y0:.1f}" x2="{x1:.1f}" y2="{y1:.1f}" stroke="#8A2E2E" stroke-width="1"/>')
            xl,yl = _polar(cx,cy,r_outer+16,lon)
            parts.append(f'<text x="{xl:.1f}" y="{yl:.1f}" font-size="8" fill="#8A2E2E" text-anchor="middle" dominant-baseline="middle">ASC</text>')
        except (ValueError, KeyError, TypeError):
            pass

    parts.append('</svg>')
    return "".join(parts)

def fmt_profil(p, avec_transits=False):
    j,m,a = p['jour'],p['mois'],p['annee']
    pr,nm = p['prenom'],p.get('nom','')
    num = {
        'cdv': chemin_de_vie(j,m,a),
        'expr': expression(pr,nm),
        'intime': intime(pr,nm),
        'real': realisation(pr,nm),
        'ap': annee_perso(j,m),
    }
    astro = calc_theme(j,m,a,p.get('ville','Marseille'),p.get('heure'),p.get('minute',0),p.get('asc_force'))
    heure_str = f"{p['heure']:02d}h{p.get('minute',0):02d}" if p.get('heure') is not None else "heure inconnue"
    filiation = p.get('filiation', '')
    filiation_str = f"\n  Filiation     : {filiation}" if filiation else ""
    fratrie = p.get('fratrie', '')
    fratrie_str = f"\n  Fratrie       : {fratrie}" if fratrie else ""

    chiffres = analyse_chiffres(j, m, a)
    num_pin, val_pin, reste_pin = pinnacles(j, m, a)
    ap, theme_ap, energie_ap, focus_ap = annee_perso_detaillee(j, m)

    dom_str = ", ".join(f"{d} ({sig})" for d, sig in chiffres['dominants']) or "aucun"
    man_str = ", ".join(f"{mn} ({sig})" for mn, sig in chiffres['manquants']) or "aucun"

    pin_str = f"Pinnacle {num_pin} -- valeur {val_pin}"
    if reste_pin:
        pin_str += f" (encore {reste_pin} ans dans ce cycle)"
    else:
        pin_str += " (dernier cycle, permanent)"

    genre = p.get('genre', '')
    genre_str = f" -- {genre}" if genre else ""
    aujourdhui = date.today()
    age_actuel = aujourdhui.year - a - ((aujourdhui.month, aujourdhui.day) < (m, j))

    lines = [
        f"PROFIL : {pr} {nm}{genre_str}",
        f"Né le {j:02d}/{m:02d}/{a} à {p.get('ville','')} ({heure_str}){filiation_str}{fratrie_str}" if genre == 'Homme' else f"Née le {j:02d}/{m:02d}/{a} à {p.get('ville','')} ({heure_str}){filiation_str}{fratrie_str}" if genre == 'Femme' else f"Né(e) le {j:02d}/{m:02d}/{a} à {p.get('ville','')} ({heure_str}){filiation_str}{fratrie_str}",
        f"  Âge actuel exact (repère interne) : {age_actuel} ans au {aujourdhui.strftime('%d/%m/%Y')}",
        "",
        "NUMÉROLOGIE",
        f"  Chemin de vie : {label_nombre(num['cdv'])}",
        f"  Expression    : {label_nombre(num['expr'])}",
        f"  Intime        : {label_nombre(num['intime'])}",
        f"  Réalisation   : {label_nombre(num['real'])}",
        f"  Année perso   : {ap} -- {theme_ap}",
        f"  Énergie       : {energie_ap}",
        f"  Focus         : {focus_ap}",
        f"  Cycle de vie  : {pin_str}",
        f"  Dominants     : {dom_str}",
        f"  Manquants     : {man_str}",
        "",
        "ASTROLOGIE",
    ]
    for np, d in astro['planetes'].items():
        lines.append(f"  {np:<10}: {d['signe']} {d['degre']}°")
    if astro['ascendant']:
        asc = astro['ascendant']
        deg_str = f" {asc['degre']}°" if asc['degre'] else ""
        lines.append(f"  Ascendant  : {asc['signe']}{deg_str}")

    # Transits actuels : uniquement pour les offres qui en ont besoin dans la lecture du présent.
    if avec_transits:
        try:
            bloc_transits = calc_transits(astro['planetes'], j, m, a)
            if bloc_transits:
                lines.append(bloc_transits)
        except Exception as ex:
            print(f"[transits] Calcul ignoré : {ex}")

    # Grandes périodes charnières : injectées pour TOUTES les offres.
    # Les années brutes restent internes ; les prompts doivent les regrouper en 2 à 4 fenêtres maximum.
    try:
        bloc_charnieres = calcul_charnieres_prompt(j, m, a, pr)
        if bloc_charnieres:
            lines.append(bloc_charnieres)
    except Exception as ex:
        print(f"[charnieres] Calcul ignoré : {ex}")

    return "\n".join(lines), num, astro

