def _get_logo_b64():
    """Retourne le logo base64 -- d'abord la version embarquée (validée), sinon depuis static/.
    Si la chaîne embarquée est corrompue/tronquée (ex. copier-coller cassé lors d'un déploiement),
    on ne veut jamais un logo invisible en silence : on retombe sur le symbole ✦."""
    if LOGO_B64_EMBEDDED:
        try:
            raw = base64.b64decode(LOGO_B64_EMBEDDED, validate=True)
            if raw[:8] == b'\x89PNG\r\n\x1a\n':
                return LOGO_B64_EMBEDDED
            print("[logo] LOGO_B64_EMBEDDED invalide (signature PNG absente) -- fallback")
        except Exception as e:
            print(f"[logo] LOGO_B64_EMBEDDED corrompu : {e} -- fallback")
    candidats = [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), 'static', 'logo-main.png'),
        os.path.join(os.getcwd(), 'static', 'logo-main.png'),
        '/opt/render/project/src/static/logo-main.png',
        'static/logo-main.png',
    ]
    for logo_path in candidats:
        if os.path.exists(logo_path):
            print(f"[logo] Trouvé : {logo_path}")
            try:
                with open(logo_path, 'rb') as f:
                    return base64.b64encode(f.read()).decode('utf-8')
            except Exception as e:
                print(f"[logo] Erreur lecture : {e}")
    return ''


def generer_pdf_imprimable(offre, clients, narratif, astros=None, type_analyse='adulte'):
    annee = date.today().year
    est_naissance = (type_analyse == 'naissance')
    def _esc(v):
        return html_lib.escape(str(v or ''), quote=True)

    if est_naissance:
        noms_display = _esc(f"{_prenom_affiche(clients[0]['prenom'])} {clients[0].get('nom','')}".strip())
        tagline = "Une boussole de naissance à relire à chaque étape de la vie."
    elif offre == 'solo':
        noms_display = _esc(f"{_prenom_affiche(clients[0]['prenom'])} {clients[0].get('nom','')}".strip())
        tagline = "Ce que ta date de naissance révèle de qui tu es vraiment."
    elif offre == 'couple':
        noms_display = f"{_esc(_prenom_affiche(clients[0]['prenom']))} &amp; {_esc(_prenom_affiche(clients[1]['prenom']))}"
        tagline = "Ce que vos différences révèlent de votre lien, et ce que vous pouvez en construire."
    elif offre == 'vocation':
        noms_display = _esc(" · ".join(_prenom_affiche(c['prenom']) for c in clients))
        tagline = "Comprendre ta voie, explorer tes possibilités, éclairer une reconversion."
    else:
        noms_display = _esc(" · ".join(_prenom_affiche(c['prenom']) for c in clients))
        tagline = "Ce que votre lignée vous a transmis, et ce que vous pouvez en faire."

